Record frw := FRW { f_ret : word; f_v0 : word; f_v1 : word; f_v2 : word; f_v3 : word; f_v4 : word; f_v5 : word; f_v6 : word;
                    f_v7 : word; f_v8 : word; f_v9 : word; f_v10 : word; f_v11 : word }.

