Definition rgcells (M : word -> option byte) (s : Z) (f : frw) (fl : word) : Prop :=
  rlcells M s (f_ret f) (f_v0 f) (f_v1 f) (f_v2 f) (f_v3 f) (f_v4 f) (f_v5 f) (f_v6 f) (f_v7 f) (f_v8 f) (f_v9 f) (f_v10 f) (f_v11 f)
  /\ rdn SEGS M (Z_to_bv 64 (s - 112)) 8 = Some (word_to_le_bytes 8 fl).

