(* [comment removed for export] *)
Definition rg_ok (C : lctx) (Ar A : AS) (md : Model) (s datad nd datas ns : Z) : Prop :=
  Cok C /\ (s mod 16 = 0)%Z /\ (c_top C - LSTK + ROPLOW_STACK <= s)%Z /\ (s + 64 <= c_top C)%Z /\ sub_live Ar A /\
  live A (Z_to_bv 64 datad) = Some nd /\ live Ar (Z_to_bv 64 datad) = None /\ live (c_A0 C) (Z_to_bv 64 datad) = None /\
  live A (Z_to_bv 64 datas) = Some ns /\ (0 <= datad < 2 ^ 64)%Z /\ (0 <= datas < 2 ^ 64)%Z /\ (0 < nd)%Z /\ (0 < ns)%Z.

(* [comment removed for export] *)
Definition rg_st (C : lctx) (Ar A : AS) (md : Model) (s datad nd : Z) (m0 : word -> option byte) (f : frw) (fl : word) (m : word -> option byte) : Prop :=
  W C A m md /\ POSTM C Ar s m0 m /\ rgcells m s f fl /\ (forall a : word, ~ scratch C s a -> ~ (datad <= u a < datad + nd)%Z -> m a = m0 a).

