Lemma rg_G_W : forall (n : nat) C Ar A md (s : Z) (S : TSet) (f : frw) (fl : word)
    (datad nd datas ns psF pdF nfw swpl dwpl dh : Z) (r0 : bvmap 5 word) m0 m r (i : Z),
  rg_ok C Ar A md s datad nd datas ns -> (1 <= nfw < 2 ^ 26)%Z ->
  (1 <= dh < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z ->
  (forall i', 0 <= i' < dh -> datad <= pdF + 4 * dwpl * i' /\ pdF + 4 * dwpl * i' + 4 * nfw <= datad + nd)%Z ->
  (forall i', 0 <= i' < dh -> datas <= psF + 4 * swpl * i' /\ psF + 4 * swpl * i' + 4 * nfw + 4 <= datas + ns)%Z ->
