(* [comment removed for export] *)
Lemma rg_K2 : forall C Ar A md (s : Z) (S : TSet) (f : frw) (nofull nolast f3 : bool)
    (datad nd datas ns psF pdF psl pdl nfw swpl dwpl dh x3 : Z) (m0 m : word -> option byte) (r : bvmap 5 word),
  rg_ok C Ar A md s datad nd datas ns ->
  (1 <= dh < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z -> (x3 = if f3 then 0 else 4)%Z ->
  (0 <= nfw < 2 ^ 26)%Z -> (nofull = false -> 1 <= nfw)%Z ->
  (nofull = false -> forall i', 0 <= i' < dh -> datad <= pdF + 4 * dwpl * i' /\ pdF + 4 * dwpl * i' + 4 * nfw <= datad + nd)%Z ->
  (nofull = false -> forall i', 0 <= i' < dh -> datas <= psF + 4 * swpl * i' /\ psF + 4 * swpl * i' + 4 * nfw + 4 <= datas + ns)%Z ->
  (nolast = false -> forall i', 0 <= i' < dh -> datad <= pdl + 4 * dwpl * i' /\ pdl + 4 * dwpl * i' + 4 <= datad + nd)%Z ->
  (nolast = false -> forall i', 0 <= i' < dh -> datas <= psl + 4 * swpl * i' /\ psl + 4 * swpl * i' + 4 + x3 <= datas + ns)%Z ->
  ret_ok (f_ret f) ->
  rg_st C Ar A md s datad nd m0 f (Z_to_bv 64 (if nolast then 1 else 0)) m ->
  getr r 2 = Z_to_bv 64 (s - 112) -> getr r 13 = Z_to_bv 64 swpl -> getr r 14 = Z_to_bv 64 dwpl -> getr r 12 = Z_to_bv 64 dh ->
  getr r 19 = Z_to_bv 64 (if nofull then 1 else 0) -> getr r 28 = Z_to_bv 64 nfw ->
  (nofull = false -> getr r 9 = Z_to_bv 64 psF /\ getr r 29 = Z_to_bv 64 pdF) ->
  (nolast = false -> getr r 5 = Z_to_bv 64 pdl /\ getr r 26 = Z_to_bv 64 psl /\ getr r 30 = Z_to_bv 64 (if f3 then 1 else 0)) ->
  (forall m' r', rg_st C Ar A md s datad nd m0 f (Z_to_bv 64 (if nolast then 1 else 0)) m' -> rg_post f s r r' ->
     realizes SEGS (mkCfg (mkst r' (f_ret f) m' al_rom) md) S) ->
